const date=value=>{if(!value||value==='unknown')return t('noInfo');const parsed=new Date(value);return Number.isNaN(parsed.getTime())?t('noInfo'):new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-US',{day:'numeric',month:'short',year:'numeric'}).format(parsed);};
