function stopConductorMotion(){clearTimeout(motionTimer);for(const svg of document.querySelectorAll('.stage-chief svg'))svg.classList.remove('is-conducting','motion-opt-in');}
function updateMotionHint(){if($('motion-hint'))$('motion-hint').textContent=window.matchMedia('(prefers-reduced-motion: reduce)').matches?t('motionReducedHint'):t('motionButtonHint');}
function replayConductor(explicit){const chief=(report?.orchestra?.actors||[]).find(item=>item.kind==='conductor');if(!chief||selectedActorId!==chief.id)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced&&!explicit){updateMotionHint();return;}const svg=document.querySelector('.stage-chief svg');if(!svg)return;stopConductorMotion();void svg.getBoundingClientRect();svg.classList.toggle('motion-opt-in',reduced&&explicit);svg.classList.add('is-conducting');$('motion-hint').textContent=t('motionPlayed');motionTimer=setTimeout(()=>{svg.classList.remove('is-conducting','motion-opt-in');updateMotionHint();},2400);}
function showActor(id){const actors=report?.orchestra?.actors||[],actor=actors.find(item=>item.id===id),card=$('actor-card');card.replaceChildren();for(const button of document.querySelectorAll('[data-actor]'))button.setAttribute('aria-pressed',String(button.dataset.actor===selectedActorId));if(!actor){card.hidden=true;return;}card.hidden=false;const labels=actorLabels(actor),heading=make('div','actor-card-head');heading.append(make('h4','',actorTitle(actor)),make('strong','',actor.total_tokens===null?t('noInfo'):`${number(actor.total_tokens)} ${t('tokenUnit')}`));card.append(heading,make('p','actor-model',labels.modelText+' · '+t(labels.model.source==='configured'?'configuredSource':labels.model.source==='observed'?'observedSource':'noInfo')),make('p','actor-model',labels.effortText+' · '+t(labels.effort.source==='configured'?'configuredSource':labels.effort.source==='observed'?'observedSource':'noInfo')));if(actor.kind==='conductor')card.append(make('p','actor-share',t('chiefPolicy')));if(actor.total_tokens===null){card.append(make('p','actor-share',t('actorNoUsage')));return;}const total=report.orchestra.total_tokens||0;card.append(make('p','actor-share',t('shareOfTotal',number(total?Math.round(actor.total_tokens/total*100):0))));const pairs=actor.model_efforts||[];if(pairs.length>1){const list=make('ul','actor-model-list');for(const pair of pairs)list.append(make('li','',`${chartLabel('model',pair.model)} · ${effortLabel(pair.effort)} · ${number(pair.total_tokens)} ${t('tokenUnit')}`));card.append(make('p','actor-model',t('modelEffortBreakdown')),list);}const metrics=make('div','actor-metrics');for(const [key,label] of [['input_tokens','readTokens'],['output_tokens','writeTokens'],['cached_input_tokens','cacheTokens']])metrics.append(make('span','',`${t(label)}: ${number(actor[key])}`));card.append(metrics,make('p','actor-footnote',t('cacheIncluded')));}
function renderOrchestra(){if(!report?.orchestra)return;const data=report.orchestra,scopes=baseReport?.orchestra?.scopes||data.scopes,selector=$('root-filter'),old=activeRoot;selector.replaceChildren();if(!scopes.length)selector.append(new Option(t('noInfo'),''));else for(const [index,scope] of scopes.entries())selector.append(new Option(t('workOption',shortProject(scope.project),index+1),scope.id));selector.value=old;selector.disabled=!scopes.length;$('stage-total').textContent=report.records_observed?`${number(data.total_tokens)} ${t('tokenUnit')}`:t('noInfo');$('stage-conductor').textContent=data.actors.some(item=>item.kind==='conductor'&&item.total_tokens!==null)?`${number(data.conductor_tokens)} ${t('tokenUnit')}`:t('noInfo');$('stage-helper-count').textContent=number(data.helper_count);const stage=$('stage-actors');stopConductorMotion();stage.replaceChildren();const actors=data.actors||[],conductor=actors.find(item=>item.kind==='conductor'),helpers=actors.filter(item=>item.kind==='helper');$('stage-empty').hidden=Boolean(data.selected_root&&actors.length);$('stage-empty').textContent=t('noAgents');if(data.selected_root&&actors.length){const chief=make('div','stage-chief');if(conductor)chief.append(actorButton(conductor));stage.append(chief);const section=make('div','stage-helpers');for(const helper of helpers.slice(0,12))section.append(actorButton(helper));stage.append(section);if(helpers.length>12){const more=make('details','more-helpers');more.append(make('summary','',t('moreHelpers',helpers.length-12)));const list=make('div','more-helper-list');for(const helper of helpers.slice(12))list.append(actorButton(helper));more.append(list);stage.append(more);}}if(!actors.some(item=>item.id===selectedActorId))selectedActorId=conductor?.id||helpers[0]?.id||'';showActor(selectedActorId);$('animate-chief').disabled=!conductor;updateMotionHint();const total=data.total_tokens||0,chief=data.conductor_tokens||0,helper=data.helper_tokens||0,unknown=data.unassigned_tokens||0,pct=value=>total?value/total*100:0;$('share-track').style.background=`linear-gradient(to right,#e8b866 0 ${pct(chief)}%,#75a5c9 ${pct(chief)}% ${pct(chief+helper)}%,#b8ada5 ${pct(chief+helper)}% 100%)`;$('share-track').setAttribute('aria-label',`${t('tokenShares')}: ${t('chiefShare')} ${number(chief)}, ${t('helperShare')} ${number(helper)}, ${t('unknownShareLabel')} ${number(unknown)}`);$('share-caption').textContent=t('scopeHint');$('share-legend').replaceChildren();for(const [kind,label,value] of [['chief','chiefShare',chief],['helpers','helperShare',helper],['unknown','unknownShareLabel',unknown]])$('share-legend').append(make('span',kind,`${t(label)} ${number(value)} ${t('tokenUnit')}`));}
function renderUsage(){if(!report)return;$('sample-badge').hidden=!report.sample_data;const available=report.status==='available'&&report.records_observed>0;$('usage-empty').hidden=available;$('usage-empty').textContent=!baseReport?.records_observed?t('sourceMissing'):t('usageEmpty');$('metrics').replaceChildren();const counterPresent=name=>report.records.some(record=>Object.hasOwn(record.usage,name));for(const [key,label] of [['total_tokens','totalText'],['input_tokens','readText'],['output_tokens','writtenText'],['cached_input_tokens','reusedText']]){const card=make('div','metric');card.append(make('span','metric-label',t(label)),make('strong','',available&&counterPresent(key)?number(report.totals[key]):t('noInfo')),make('span','metric-unit',t('tokenUnit')));$('metrics').append(card);}$('usage-help').textContent=available?t('cacheHelp'):'';$('source').textContent=t('sourceLocal')+' '+t('sourceSelected')+': '+readable(report.source_path);$('limits').textContent=t('limitsShort')+' '+t('chartSource');if(baseReport){optionList('project-filter',baseReport.groups.map(item=>item.project),'allProjects',shortProject);optionList('thread-filter',baseReport.groups.map(item=>item.thread),'allWork',workLabel);}renderCharts();}
function renderWork(){if(!report)return;const items=workGroups();$('work-list').replaceChildren();$('work-empty').hidden=items.length>0;$('work-empty').textContent=t('workEmpty');for(const item of items){const card=make('article','work-card');card.append(make('h3','',workLabel(item.thread)));const last=item.records.map(record=>record.timestamp).filter(value=>value&&value!=='unknown').sort().at(-1);card.append(make('p','',shortProject(item.project)+' · '+t('workDate')+': '+date(last)));card.append(make('span','amount',number(item.usage.total_tokens)+' '+t('tokenUnit')));const details=make('details');details.append(make('summary','',t('workDetails')));const dl=make('dl');for(const [term,value] of [[t('workId'),readable(item.thread)],[t('project'),readable(item.project)],[t('workStatus'),t('noInfo')],[t('workRecords',item.records.length),'']]){const dt=make('dt','',term);const dd=make('dd','',value);dl.append(dt,dd);}details.append(dl);for(const record of item.records){const bits=[date(record.timestamp),readable(record.model),t(ROLE_KEYS[record.role]||'noInfo'),t(record.semantics==='request'?'request':'cumulative'),number(record.usage.total_tokens)+' '+t('tokenUnit')];details.append(make('div','record-item',bits.join(' · ')));}card.append(details);$('work-list').append(card);}}
async function loadUsage(initial=false){const query=new URLSearchParams(new FormData($('filters')));if(initial){baseReport=await api('/api/usage?'+query);activeRoot=baseReport.orchestra?.scopes?.[0]?.id||'';}if(activeRoot)query.set('root',activeRoot);report=initial&&!activeRoot?baseReport:await api('/api/usage?'+query);renderUsage();renderOrchestra();renderWork();if(!initial)recordActivity('usageRefreshed');}
function selectTab(name){activeTab=name;for(const button of document.querySelectorAll('[data-tab]')){const active=button.dataset.tab===name;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));$(button.dataset.tab).hidden=!active;}}
$('language').addEventListener('change',event=>{lang=event.target.value==='en'?'en':'tr';try{localStorage.setItem('codex-console-language',lang);}catch(_){}renderStatic();});
for(const radio of document.querySelectorAll('input[name="profile-choice"]'))radio.addEventListener('change',()=>choosePreset(radio.value));
$('other-preset').addEventListener('change',event=>{if(event.target.value)choosePreset(event.target.value);});
$('roles').addEventListener('input',()=>{selectedPreset='custom';syncPreset();renderOtherEffect();invalidate();});
$('roles').addEventListener('change',event=>{if(event.target.matches('select[data-kind=model]')){const card=event.target.closest('.role-card');card.dataset.model=event.target.value;refreshModelOptions(card);refreshEffortOptions(card,true);}selectedPreset='custom';syncPreset();renderOtherEffect();invalidate();});
$('concurrency').addEventListener('input',invalidate);
$('concurrency').addEventListener('change',resizeTeam);
$('team-slots').addEventListener('input',event=>{const field=event.target.dataset.field;if(field!=='title')return;const index=Number(event.target.closest('.team-slot')?.dataset.index);if(teamState[index])teamState[index].title=event.target.value;invalidate();});
$('team-slots').addEventListener('change',event=>{const field=event.target.dataset.field,index=Number(event.target.closest('.team-slot')?.dataset.index),item=teamState[index];if(!item)return;if(field==='title'){item.title=event.target.value;invalidate();return;}if(!['duty','model','effort'].includes(field))return;item[field]=event.target.value;if(field==='duty'){const choice=roleValues()[item.duty];item.model=choice.model;item.effort=choice.effort;}if(field==='model'){const efforts=modelEntry(item.model)?.efforts||[];if(efforts.length&&!efforts.includes(item.effort))item.effort=efforts[0];}renderTeam();invalidate();});
$('refresh-models').addEventListener('click',async()=>{const button=$('refresh-models');button.disabled=true;try{catalog=await api('/api/models/refresh',{});updateRoleLabels();renderTeam();renderModelSource();invalidate();recordActivity('modelsRefreshed');}catch(error){showError(error);}finally{button.disabled=false;}});
$('settings-form').addEventListener('submit',checkChanges);$('save').addEventListener('click',save);$('restore').addEventListener('click',restore);
for(const button of document.querySelectorAll('[data-tab]'))button.addEventListener('click',()=>selectTab(button.dataset.tab));
$('filters').addEventListener('submit',event=>{event.preventDefault();activeRange='custom';for(const button of document.querySelectorAll('[data-range]'))button.classList.remove('active');loadUsage().catch(showError);});
$('root-filter').addEventListener('change',event=>{activeRoot=event.target.value;selectedActorId='';loadUsage().catch(showError);});
window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{stopConductorMotion();updateMotionHint();});
$('animate-chief').addEventListener('click',()=>{const chief=(report?.orchestra?.actors||[]).find(item=>item.kind==='conductor');if(!chief)return;selectedActorId=chief.id;showActor(chief.id);replayConductor(true);});
$('quit-console').addEventListener('click',async()=>{try{await api('/api/quit',{});$('activity-title').textContent=t('consoleClosed');$('activity-next').textContent='';$('quit-console').disabled=true;}catch(error){showError(error);}});
for(const button of document.querySelectorAll('[data-range]'))button.addEventListener('click',()=>{activeRange=button.dataset.range;for(const item of document.querySelectorAll('[data-range]'))item.classList.toggle('active',item===button);const now=new Date();const end=now.toISOString().slice(0,10);const start=new Date(now);start.setUTCDate(start.getUTCDate()-Number(activeRange)+1);$('filters').elements.date_from.value=activeRange==='all'?'':start.toISOString().slice(0,10);$('filters').elements.date_to.value=activeRange==='all'?'':end;loadUsage().catch(showError);});
renderStatic();(async()=>{try{await loadSettings(true);}catch(error){showError(error);}try{await loadUsage(true);}catch(error){showError(error);}})();
